use std::{alloc::{GlobalAlloc, Layout, System}, path::Path, sync::atomic::{AtomicU64, Ordering}, time::Instant};
use gwt::cli::execution_state::{self as execution, ExecutionGenerationLedger, ExecutionOwnerKey};

struct CountingAllocator;
static ALLOCATIONS: AtomicU64 = AtomicU64::new(0);
static ALLOCATED_BYTES: AtomicU64 = AtomicU64::new(0);
unsafe impl GlobalAlloc for CountingAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        ALLOCATED_BYTES.fetch_add(layout.size() as u64, Ordering::Relaxed);
        unsafe { System.alloc(layout) }
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        ALLOCATED_BYTES.fetch_add(layout.size() as u64, Ordering::Relaxed);
        unsafe { System.alloc_zeroed(layout) }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        ALLOCATIONS.fetch_add(1, Ordering::Relaxed);
        ALLOCATED_BYTES.fetch_add(size as u64, Ordering::Relaxed);
        unsafe { System.realloc(ptr, layout, size) }
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) { unsafe { System.dealloc(ptr, layout) } }
}
#[global_allocator]
static ALLOCATOR: CountingAllocator = CountingAllocator;

fn main() {
    let args: Vec<_> = std::env::args().collect();
    if args[1] == "capture" {
        let path = Path::new(&args[2]);
        let record = execution::load(path).unwrap().unwrap();
        assert!(execution::integrity_ok(&record));
        let owner = ExecutionOwnerKey { kind: record.owner_kind, number: record.owner_number };
        let ledger = execution::load_generation_ledger(path, owner).unwrap().unwrap();
        std::fs::write(&args[3], serde_json::to_vec(&ledger).unwrap()).unwrap();
        return;
    }
    let input = std::fs::read(&args[2]).unwrap();
    let ledger: ExecutionGenerationLedger = serde_json::from_slice(&input).unwrap();
    assert!(execution::generation_ledger_integrity_ok(&ledger));
    let initial = ledger.clone();
    for _ in 0..5 { assert!(execution::generation_ledger_integrity_ok(std::hint::black_box(&ledger))); }
    ALLOCATIONS.store(0, Ordering::Relaxed);
    ALLOCATED_BYTES.store(0, Ordering::Relaxed);
    let start = Instant::now();
    for _ in 0..50 { assert!(execution::generation_ledger_integrity_ok(std::hint::black_box(&ledger))); }
    let ns = start.elapsed().as_nanos();
    let allocations = ALLOCATIONS.load(Ordering::Relaxed);
    let allocated_bytes = ALLOCATED_BYTES.load(Ordering::Relaxed);
    assert_eq!(ledger, initial);
    assert_eq!(input, std::fs::read(&args[2]).unwrap());
    println!("{{\"elapsed_ns\":{ns},\"allocations\":{allocations},\"allocated_bytes\":{allocated_bytes},\"validations\":50,\"generations\":{},\"ledger_hash\":\"{}\",\"input_unchanged\":true}}", ledger.generations.len(), ledger.content_hash);
}
